import{_ as a,o as t,c as s,a3 as n}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Archive Layout","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Archive Layout | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/layout"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/layout"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/layout"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/layout"}]]},"headers":[],"relativePath":"xclang/reference/layout.md","filePath":"en/xclang/reference/layout.md","lastUpdated":1791266105000}'),o={name:"xclang/reference/layout.md"};function l(c,e,i,d,r,h){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="archive-layout" tabindex="-1">Archive Layout <a class="header-anchor" href="#archive-layout" aria-label="Permalink to &quot;Archive Layout&quot;">​</a></h1><p>What an unpacked toolchain archive holds: the toolchain directory, <code>$XCLANG</code> in these docs. Every host archive holds every sysroot; the archives differ only in the programs of <code>bin/</code>. Why it is laid out this way is in <a href="./../design/toolchain">toolchain structure</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xclang/</span></span>
<span class="line"><span>  bin/                     llvm and its names (clang, clang++, clang-cl,</span></span>
<span class="line"><span>                           clang-scan-deps, ld.lld, ld64.lld, lld-link,</span></span>
<span class="line"><span>                           llvm-ar, llvm-objcopy, windres, dsymutil,</span></span>
<span class="line"><span>                           llvm-gsymutil, ...), the tools outside it</span></span>
<span class="line"><span>                           (llvm-profdata, llvm-cov, llvm-dwarfdump,</span></span>
<span class="line"><span>                           llvm-strings, FileCheck), and &lt;target&gt;.cfg for</span></span>
<span class="line"><span>                           every spelling of every target</span></span>
<span class="line"><span>  lib/clang/&lt;major&gt;/       clang&#39;s resource headers, compiler-rt&#39;s headers,</span></span>
<span class="line"><span>                           and compiler-rt for every target</span></span>
<span class="line"><span>  lib/cmake/xclang/        the CMake package</span></span>
<span class="line"><span>  lib/libLTO.dylib         macOS hosts: LTO for the system&#39;s ld (-fuse-ld=ld)</span></span>
<span class="line"><span>  &lt;target&gt;/                the sysroot of each target (below)</span></span>
<span class="line"><span>  sdk/                     not in the archive: the vendor SDKs that the</span></span>
<span class="line"><span>                           unreleased xclang command fetches, and</span></span>
<span class="line"><span>                           sdk/windows, sdk/macos, those in use</span></span></code></pre></div><p>The <a href="./../design/roadmap#msvc">unreleased</a> MSVC targets have no sysroot: their compiler-rt is <code>lib/clang/&lt;major&gt;/lib/windows</code>, their C and C++ libraries are the fetched SDK&#39;s.</p><h2 id="sysroots" tabindex="-1">Sysroots <a class="header-anchor" href="#sysroots" aria-label="Permalink to &quot;Sysroots&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Linux</th><th>Windows (MinGW)</th><th>macOS</th></tr></thead><tbody><tr><td>C library</td><td>glibc 2.17&#39;s headers in <code>usr/include</code>, its startup files and libraries in <code>lib64</code>, <code>usr/lib64</code></td><td>mingw-w64 (UCRT) and winpthreads in <code>include</code>, <code>lib</code></td><td>none: Apple&#39;s SDK, Xcode&#39;s, or on Linux and Windows hosts <code>sdk/macos</code> (<a href="./../design/roadmap#macos-any-host">unreleased</a>)</td></tr><tr><td>libc++, libc++abi, libunwind</td><td><code>usr/include/c++/v1</code>, <code>usr/lib</code></td><td><code>include/c++/v1</code>, <code>lib</code></td><td><code>include/c++/v1</code>, <code>lib</code> (no libunwind: the system&#39;s, in libSystem)</td></tr><tr><td>libc++ module sources</td><td><code>usr/share/libc++/v1</code></td><td><code>share/libc++/v1</code></td><td><code>share/libc++/v1</code></td></tr><tr><td>libc++ module manifest</td><td><code>usr/lib/libc++.modules.json</code></td><td><code>lib/libc++.modules.json</code></td><td><code>lib/libc++.modules.json</code></td></tr><tr><td>ASan libc++</td><td><code>usr/lib/asan</code></td><td>none</td><td><code>lib/asan</code></td></tr><tr><td>GCC library names</td><td>empty <code>libatomic.a</code>, <code>libgcc.a</code>, <code>libgcc_eh.a</code>, <code>libgcc_s.a</code></td><td>the same, and <code>libssp.a</code>, <code>libssp_nonshared.a</code></td><td>none</td></tr></tbody></table><p><code>clang++ --target=&lt;target&gt; -print-library-module-manifest-path</code> prints the path of the manifest. Why the GCC names are empty archives is in <a href="./../design/hermeticity#gcc-library-names">hermeticity</a>.</p><h2 id="without-links" tabindex="-1">Without Links <a class="header-anchor" href="#without-links" aria-label="Permalink to &quot;Without Links&quot;">​</a></h2><p>On Linux and macOS hosts, the tool names in <code>bin/</code> are symbolic links to <code>llvm</code>. The Windows archives hold no symbolic links, so they unpack without extra rights, and conda can package them; every tool name is a small <a href="./../design/windows#the-launchers">launcher</a> instead. The Linux sysroots hold no links either: soname links are the files themselves, and <code>libfoo.so</code> links are linker scripts (<a href="./../design/hermeticity#why-glibc-2-17">why glibc 2.17</a>).</p>`,9)])])}const u=a(o,[["render",l]]);export{m as __pageData,u as default};
